<?php

declare(strict_types=1);

namespace App\Modules\Platform\Migration\Dto;

/**
 * Operator-supplied crosswalk. `organizations` maps legacy org codes to new
 * org unit ids; `employments` maps legacy employee numbers to new employment
 * ids. Values are validated as integers; no id is generated by the framework.
 */
final class MappingSet
{
    public const TYPE_ORGANIZATION = 'ORGANIZATION';

    public const TYPE_EMPLOYMENT = 'EMPLOYMENT';

    /**
     * @param  array<string, int>  $organizations
     * @param  array<string, int>  $employments
     */
    public function __construct(
        public readonly array $organizations = [],
        public readonly array $employments = [],
        public readonly string $sourceHash = '',
    ) {}

    public function organizationId(string $code): ?int
    {
        return $this->organizations[$code] ?? null;
    }

    public function employmentId(string $employeeNo): ?int
    {
        return $this->employments[$employeeNo] ?? null;
    }

    public function hasOrganizations(): bool
    {
        return $this->organizations !== [];
    }

    public function hasEmployments(): bool
    {
        return $this->employments !== [];
    }
}
